-- Alice's Library -- atualização do catálogo (rodar DEPOIS de livros.sql, uma vez; pode repetir).
-- 1) colunas novas  2) sinopses específicas (pt e en)  3) quais livros têm texto dentro do app e a estante inicial.
-- Observação: a estante de leitura de cada pessoa fica no aparelho (IndexedDB), não nesta tabela;
-- 'estante_inicial' só marca quais livros o app coloca na estante no primeiro uso.

begin;

alter table public.livros add column if not exists resumo_en text;
alter table public.livros add column if not exists texto_no_app boolean not null default false;
alter table public.livros add column if not exists texto_slug text;
alter table public.livros add column if not exists texto_fonte text;
alter table public.livros add column if not exists estante_inicial boolean not null default false;

update public.livros set resumo = 'Black Beauty, um cavalo de pelagem negra, conta a própria vida: dos prados da infância na Inglaterra a donos gentis, a donos cruéis e aos anos puxando carros de aluguel em Londres. Pelo caminho encontra a égua Ginger e o pônei Merrylegs, e vê o que o cansaço e os maus-tratos fazem com os animais. O livro foi escrito para pedir bondade com os cavalos.', resumo_en = 'Black Beauty, a black horse, tells his own life story: from a happy English meadow to kind masters, cruel ones, and hard years pulling London cabs. Along the way he meets the mare Ginger and the pony Merrylegs and sees what overwork and cruelty do to animals. The book was written as a plea for kindness to horses.', texto_no_app = true, texto_slug = 'anna-sewell_black-beauty', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'a6a3854e-6978-5d7e-af02-37cbaf8a1e80';
update public.livros set resumo = 'O doutor Watson volta ferido do Afeganistão e divide um apartamento na Baker Street com um sujeito estranho, Sherlock Holmes. Quando um homem aparece morto numa casa vazia de Londres, com a palavra RACHE escrita na parede, Holmes mostra seu método de dedução pela primeira vez. A segunda metade do livro viaja ao deserto de Utah para explicar o motivo do crime.', resumo_en = 'Dr Watson returns wounded from Afghanistan and shares rooms on Baker Street with an odd fellow named Sherlock Holmes. When a man is found dead in an empty London house with the word RACHE scrawled on the wall, Holmes shows his method of deduction for the first time. The second half of the book travels to the Utah desert to explain the motive.', texto_no_app = true, texto_slug = 'arthur-conan-doyle_a-study-in-scarlet', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '50f7d8cf-8c16-5360-8442-406e8d005217';
update public.livros set resumo = 'Doze contos narrados por Watson mostram Holmes em casos bem diferentes: o rei da Boêmia e a astuta Irene Adler, a Liga dos Cabeças-Vermelhas, a banda malhada que mata dentro de um quarto trancado. Cada história é curta, tem um enigma e uma solução que parece óbvia só depois que Holmes explica.', resumo_en = 'Twelve short stories narrated by Watson show Holmes at work on very different cases: the King of Bohemia and the clever Irene Adler, the Red-Headed League, the speckled band that kills inside a locked room. Each story is short, with a puzzle and a solution that only looks obvious once Holmes explains it.', texto_no_app = true, texto_slug = 'arthur-conan-doyle_the-adventures-of-sherlock-holmes', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '4de81066-55fa-58c6-8f2a-e94169d64fe3';
update public.livros set resumo = 'Sir Charles Baskerville aparece morto nos pântanos de Devonshire, e diz a lenda que um cão gigante e sobrenatural persegue a família. Holmes envia Watson para proteger o herdeiro, Sir Henry, na mansão isolada, enquanto investiga por conta própria. Entre a névoa, o lamaçal de Grimpen e vizinhos de aparência suspeita, o perigo cresce a cada noite.', resumo_en = 'Sir Charles Baskerville is found dead on the Devonshire moors, and legend says a giant spectral hound haunts the family. Holmes sends Watson to guard the heir, Sir Henry, at the lonely manor while he investigates on his own. Among the fog, the Grimpen Mire and suspicious neighbours, the danger grows every night.', texto_no_app = true, texto_slug = 'arthur-conan-doyle_the-hound-of-the-baskervilles', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '5fbb7ece-5e9d-5814-b527-f9dfdd2010ac';
update public.livros set resumo = 'Ebenezer Scrooge, um velho avarento, odeia o Natal e trata mal o empregado Bob Cratchit. Na véspera, o fantasma do ex-sócio Marley o avisa de que três espíritos virão: o do Natal Passado, o do Presente e o do Futuro. Depois de ver sua própria vida e a morte do pequeno Tiny Tim, Scrooge acorda decidido a mudar.', resumo_en = 'Ebenezer Scrooge, a miserly old man, hates Christmas and treats his clerk Bob Cratchit badly. On Christmas Eve the ghost of his dead partner Marley warns him that three spirits will visit: Christmas Past, Present and Yet to Come. After seeing his own life and the fate of little Tiny Tim, Scrooge wakes up determined to change.', texto_no_app = true, texto_slug = 'charles-dickens_a-christmas-carol', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '4ae7fd1b-ebd8-50d8-849d-de39d2b3b881';
update public.livros set resumo = 'Em Coketown, cidade industrial cinzenta, o professor Thomas Gradgrind educa os filhos e os alunos só com fatos e números, sem espaço para imaginação. Sua filha Louisa casa sem amor com o banqueiro Bounderby, e o filho Tom se mete em dívidas. Ao lado, o operário honesto Stephen Blackpool paga o preço de uma sociedade que trata pessoas como máquinas.', resumo_en = 'In Coketown, a grey industrial town, the schoolmaster Thomas Gradgrind raises his children and pupils on facts and figures alone, with no room for imagination. His daughter Louisa marries the banker Bounderby without love, and his son Tom slides into debt. Beside them, the honest mill hand Stephen Blackpool pays the price of a society that treats people like machines.', texto_no_app = true, texto_slug = 'charles-dickens_hard-times', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '180dcef3-09a5-5a11-bf57-42c6f8bf71aa';
update public.livros set resumo = 'Nos campos de Yorkshire, o órfão Heathcliff é criado na casa dos Earnshaw e se apaixona por Catherine, que acaba se casando com o rico Edgar Linton. Ferido, ele some e volta anos depois rico, decidido a se vingar das duas famílias. A história é contada pela criada Nelly Dean a um inquilino curioso, o senhor Lockwood.', resumo_en = 'On the Yorkshire moors, the orphan Heathcliff is raised in the Earnshaw house and falls in love with Catherine, who ends up marrying the wealthy Edgar Linton. Hurt, he disappears and returns years later rich and set on revenge against both families. The story is told by the housekeeper Nelly Dean to a curious tenant, Mr Lockwood.', texto_no_app = true, texto_slug = 'emily-bronte_wuthering-heights', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '32116ac1-1c66-504c-b9eb-5bb3638c5275';
update public.livros set resumo = 'No verão de 1922, Nick Carraway se muda para Long Island e vira vizinho do misterioso Jay Gatsby, que dá festas enormes todo fim de semana. Aos poucos Nick descobre que tudo aquilo serve para reencontrar Daisy, prima dele, hoje casada com o rico Tom Buchanan. O sonho de recuperar o passado termina em tragédia.', resumo_en = 'In the summer of 1922, Nick Carraway moves to Long Island and becomes the neighbour of the mysterious Jay Gatsby, who throws huge parties every weekend. Little by little Nick learns it is all meant to win back Daisy, his cousin, now married to the wealthy Tom Buchanan. The dream of recovering the past ends in tragedy.', texto_no_app = true, texto_slug = 'f-scott-fitzgerald_the-great-gatsby', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '1b09704e-15a7-5a85-8b87-8855b8777afb';
update public.livros set resumo = 'Sara Crewe, filha de um pai rico, estuda num internato de Londres e é tratada como princesa pela diretora, a senhorita Minchin. Quando o pai morre e a fortuna desaparece, Sara é mandada para um sótão e vira criada da escola. Ela se agarra à imaginação e à amizade da copeira Becky, até que o vizinho do lado muda o seu destino.', resumo_en = 'Sara Crewe, daughter of a wealthy father, studies at a London boarding school where Miss Minchin treats her like a princess. When her father dies and the fortune vanishes, Sara is sent to the attic and made a servant. She clings to her imagination and her friendship with the scullery maid Becky, until the neighbour next door changes her fate.', texto_no_app = true, texto_slug = 'frances-hodgson-burnett_a-little-princess', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '486a3c7e-6f0c-5124-bb8f-dfa5b6f089ec';
update public.livros set resumo = 'Mary Lennox, uma menina mimada, perde os pais na Índia e vai morar numa mansão enorme em Yorkshire com um tio distante. Ali ela ouve choros à noite, descobre um jardim trancado há dez anos e ganha a ajuda do menino Dickon. Cuidar do jardim muda Mary e também o primo doente, Colin, escondido num quarto da casa.', resumo_en = 'Mary Lennox, a spoiled girl, loses her parents in India and goes to live in a huge Yorkshire manor with a distant uncle. There she hears crying at night, finds a garden locked for ten years and gets help from a boy named Dickon. Tending the garden changes Mary and also her sick cousin Colin, hidden away in a room of the house.', texto_no_app = true, texto_slug = 'frances-hodgson-burnett_the-secret-garden', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '540bd37f-fb2b-53ba-869f-c114c098d20c';
update public.livros set resumo = 'Frederick Douglass conta como nasceu escravizado em Maryland, sem saber a própria idade, e como aprendeu a ler escondido, mesmo proibido. Relata os castigos, a luta corpo a corpo contra o feitor Covey e a fuga para o Norte em 1838. Publicado em 1845, o livro virou uma das armas mais fortes do movimento abolicionista.', resumo_en = 'Frederick Douglass tells how he was born enslaved in Maryland, not knowing his own age, and how he secretly taught himself to read despite the ban. He describes the beatings, his fight with the overseer Covey and his escape to the North in 1838. Published in 1845, the book became one of the strongest weapons of the abolitionist movement.', texto_no_app = true, texto_slug = 'frederick-douglass_narrative-of-the-life-of-frederick-douglass', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'e2b83e8a-2a88-5ed6-82c1-fcfcde87bed9';
update public.livros set resumo = 'Chesterton escreve em 1925 uma resposta às histórias da humanidade que tratam o homem como mais um animal. Na primeira parte olha para a pré-história, a arte das cavernas e as religiões antigas; na segunda, para a figura de Jesus de Nazaré. O tom é cheio de humor e paradoxos, e o raciocínio vai de imagens simples a grandes conclusões.', resumo_en = 'In 1925 Chesterton answers the popular histories that treat humankind as just another animal. The first part looks at prehistory, cave art and ancient religions; the second turns to the figure of Jesus of Nazareth. The tone is full of humour and paradox, moving from simple images to large conclusions.', texto_no_app = true, texto_slug = 'g-k-chesterton_the-everlasting-man', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'e50b5e72-477b-5cd2-9a75-e99dc6d36eec';
update public.livros set resumo = 'O professor de fonética Henry Higgins aposta com o coronel Pickering que consegue passar uma vendedora de flores, Eliza Doolittle, por duquesa, só mudando a maneira dela de falar. Eliza treina por meses e brilha num baile da alta sociedade. Depois, ela exige ser tratada como pessoa, e não como experiência, numa peça que inspirou o musical My Fair Lady.', resumo_en = 'The phonetics professor Henry Higgins bets Colonel Pickering that he can pass a flower seller, Eliza Doolittle, off as a duchess simply by changing how she speaks. Eliza trains for months and shines at a high-society ball. Afterwards she demands to be treated as a person, not an experiment, in a play that inspired the musical My Fair Lady.', texto_no_app = true, texto_slug = 'george-bernard-shaw_pygmalion', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '59548cc9-a8ec-5ae5-a9f4-7b5f4c144a48';
update public.livros set resumo = 'Shaw acompanha Joana d''Arc desde as visões que a levam a convencer o príncipe herdeiro a lhe dar um exército até o julgamento por heresia em Ruão, onde é condenada. A peça mostra tanto os soldados que a seguem quanto os bispos que a temem. Um epílogo passa-se em 1920, depois da canonização, e pergunta se o mundo estaria pronto para receber uma santa viva.', resumo_en = 'Shaw follows Joan of Arc from the visions that lead her to persuade the Dauphin to give her an army to her trial for heresy at Rouen, where she is condemned. The play shows both the soldiers who follow her and the bishops who fear her. An epilogue set in 1920, after her canonisation, asks whether the world would be ready to receive a living saint.', texto_no_app = true, texto_slug = 'george-bernard-shaw_saint-joan', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '9cbd1c12-3a58-5a88-9d13-eb7cadb6e60b';
update public.livros set resumo = 'Em pleno inverno, um desconhecido todo enfaixado chega à vila de Iping e se tranca numa pousada. Ele é Griffin, um cientista que descobriu como ficar invisível e não sabe voltar atrás. Sem dinheiro, perseguido e cada vez mais violento, procura abrigo com o antigo colega doutor Kemp, que precisa decidir o que fazer.', resumo_en = 'In the middle of winter a bandaged stranger arrives in the village of Iping and shuts himself in an inn. He is Griffin, a scientist who has found how to make himself invisible and cannot undo it. Penniless, hunted and increasingly violent, he seeks shelter with his old colleague Dr Kemp, who must decide what to do.', texto_no_app = true, texto_slug = 'h-g-wells_the-invisible-man', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'fb3f74a4-9e27-583f-bb0a-4b72fa745ce9';
update public.livros set resumo = 'Edward Prendick sobrevive a um naufrágio e é levado a uma ilha onde o doutor Moreau e o assistente Montgomery fazem experimentos. As criaturas que andam por lá são animais transformados à força em quase humanos, obrigados a seguir uma Lei. Quando a cirurgia perde o controle, a ilha vira um lugar de medo para Prendick.', resumo_en = 'Edward Prendick survives a shipwreck and is taken to an island where Dr Moreau and his assistant Montgomery run experiments. The creatures walking about are animals forced by surgery into near-human shape and made to obey a Law. When the surgery gets out of control, the island becomes a place of terror for Prendick.', texto_no_app = true, texto_slug = 'h-g-wells_the-island-of-doctor-moreau', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '112aa3e8-d110-59c7-9746-60ec125e0885';
update public.livros set resumo = 'Um inventor, chamado só de Viajante do Tempo, mostra aos amigos uma máquina e parte para o ano 802.701. Lá encontra os Eloi, gente frágil e despreocupada, e descobre que sob a terra vivem os Morlocks, que os caçam. Depois de perder a máquina e fazer amizade com a jovem Weena, ele ainda avança para um futuro em que a Terra está morrendo.', resumo_en = 'An inventor known only as the Time Traveller shows his friends a machine and sets off for the year 802,701. There he meets the Eloi, fragile and carefree, and learns that beneath the ground live the Morlocks, who hunt them. After losing his machine and befriending the young Weena, he travels on to a future in which the Earth is dying.', texto_no_app = true, texto_slug = 'h-g-wells_the-time-machine', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'b5e9ef71-ecbb-5918-a967-89d50f2a608d';
update public.livros set resumo = 'Cilindros vindos de Marte caem na região de Surrey, e deles saem máquinas de três pernas que disparam um raio de calor e soltam fumaça negra. O narrador, sem nome, foge com a esposa e depois sozinho enquanto Londres entra em pânico. Ninguém consegue deter os invasores, até que algo muito pequeno faz o trabalho.', resumo_en = 'Cylinders from Mars fall near Surrey, and out of them come three-legged machines that fire a heat ray and spread black smoke. The unnamed narrator flees, first with his wife and then alone, as London falls into panic. No one can stop the invaders, until something very small does the job.', texto_no_app = true, texto_slug = 'h-g-wells_the-war-of-the-worlds', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '432cf9da-8d3b-510b-95dd-b42f9b8f49c8';
update public.livros set resumo = 'Numa noite de Natal, alguém lê o diário de uma jovem governanta contratada para cuidar de duas crianças, Miles e Flora, numa casa de campo chamada Bly. Ela começa a ver dois vultos, os fantasmas do antigo criado Peter Quint e da governanta Miss Jessel, e acredita que querem as crianças. Até o fim, o leitor não sabe se os espíritos existem ou se ela está enlouquecendo.', resumo_en = 'On a Christmas Eve, someone reads aloud the diary of a young governess hired to look after two children, Miles and Flora, at a country house called Bly. She begins to see two figures, the ghosts of the former valet Peter Quint and the governess Miss Jessel, and believes they want the children. To the very end, the reader cannot tell whether the ghosts are real or she is losing her mind.', texto_no_app = true, texto_slug = 'henry-james_the-turn-of-the-screw', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '135c47f1-58b1-5a94-80af-7c2d7822061f';
update public.livros set resumo = 'Catherine Morland, de dezessete anos, vive devorando romances góticos e vai a Bath, onde conhece Henry Tilney e as irmãs Thorpe. Convidada para a abadia de Northanger, ela imagina segredos horríveis e crimes escondidos nos corredores. Ao ver que a realidade é bem menos sombria, aprende a separar a ficção da vida, com humor e sem perder o encanto.', resumo_en = 'Seventeen-year-old Catherine Morland, a devoted reader of Gothic novels, goes to Bath, where she meets Henry Tilney and the Thorpe siblings. Invited to Northanger Abbey, she imagines horrible secrets and hidden crimes in its corridors. Finding that reality is far less sinister, she learns to tell fiction from life, with humour and without losing her charm.', texto_no_app = true, texto_slug = 'jane-austen_northanger-abbey', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '9cba2098-f74b-57c4-b201-7e84ba8b519e';
update public.livros set resumo = 'Aos vinte e sete anos, Anne Elliot ainda pensa em Frederick Wentworth, com quem rompeu o noivado oito anos antes por conselho de uma madrinha. Ele volta rico e respeitado como capitão da marinha, e os dois passam a se encontrar em Lyme e em Bath. Entre cortesia e silêncio, o livro mostra se existe uma segunda chance quando os dois já mudaram.', resumo_en = 'At twenty-seven, Anne Elliot still thinks of Frederick Wentworth, whom she refused eight years earlier on the advice of a family friend. He returns rich and respected as a naval captain, and the two keep meeting in Lyme and in Bath. Between courtesy and silence, the book asks whether there is a second chance when both have changed.', texto_no_app = true, texto_slug = 'jane-austen_persuasion', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '4a2b4aba-3d97-54fc-af55-84998fb884ae';
update public.livros set resumo = 'Elizabeth Bennet, a segunda de cinco irmãs, vive numa família que precisa casar as filhas bem. Quando o rico Bingley aluga a mansão vizinha, ele se encanta por Jane, e o amigo orgulhoso, Darcy, se interessa por Elizabeth. Ela forma uma opinião ruim dele, apoiada nas histórias de Wickham, e só descobre os erros do próprio julgamento depois de recusar um pedido de casamento.', resumo_en = 'Elizabeth Bennet, the second of five sisters, lives in a family that must marry its daughters well. When the wealthy Bingley rents the neighbouring estate, he falls for Jane, and his proud friend Darcy takes an interest in Elizabeth. She forms a bad opinion of him, backed by Wickham''s stories, and only sees the flaws in her own judgement after refusing a marriage proposal.', texto_no_app = true, texto_slug = 'jane-austen_pride-and-prejudice', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'b4b9fa04-a1e3-5966-80ec-7af0449044fc';
update public.livros set resumo = 'Com a morte do pai, as irmãs Elinor e Marianne Dashwood perdem a casa e vão morar num chalé no campo com a mãe. Elinor é contida e racional; Marianne, apaixonada, se entrega ao charmoso Willoughby. Enquanto uma esconde a dor por Edward Ferrars e a outra sofre abertamente, o romance compara duas formas de enfrentar o amor.', resumo_en = 'After their father''s death, the sisters Elinor and Marianne Dashwood lose their home and move to a cottage in the country with their mother. Elinor is restrained and sensible; Marianne, passionate, gives herself to the charming Willoughby. While one hides her pain over Edward Ferrars and the other suffers openly, the novel compares two ways of facing love.', texto_no_app = true, texto_slug = 'jane-austen_sense-and-sensibility', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'fd1051e4-dae9-55fb-9d87-af88ec9b585b';
update public.livros set resumo = 'Lemuel Gulliver, médico de navio, faz quatro viagens que dão errado: à ilha de Lilliput, onde os habitantes têm quinze centímetros; a Brobdingnag, terra de gigantes; à ilha voadora de Laputa; e ao país dos Houyhnhnms, cavalos que falam e governam. Cada lugar serve de espelho para criticar a política, a ciência e os costumes da Inglaterra de Swift.', resumo_en = 'Lemuel Gulliver, a ship''s surgeon, makes four voyages that go wrong: to Lilliput, where the people are six inches tall; to Brobdingnag, land of giants; to the flying island of Laputa; and to the country of the Houyhnhnms, talking horses who rule. Each place serves as a mirror for criticising the politics, science and customs of Swift''s England.', texto_no_app = true, texto_slug = 'jonathan-swift_gullivers-travels', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '8e9f0d66-c932-5bbb-b6f0-425e94f9f0d5';
update public.livros set resumo = 'Numa noite no Tâmisa, o marinheiro Marlow conta aos companheiros do barco como subiu o rio Congo a serviço de uma empresa de marfim. O objetivo era encontrar Kurtz, um agente que virou lenda e que ninguém vê há meses. A viagem pela selva mostra a crueldade da colonização e o que acontece com o homem quando longe de qualquer lei.', resumo_en = 'One evening on the Thames, the sailor Marlow tells his shipmates how he went up the Congo River for an ivory company. His aim was to find Kurtz, an agent who has become a legend and whom no one has seen for months. The journey through the jungle exposes the cruelty of colonisation and what happens to a man far from any law.', texto_no_app = true, texto_slug = 'joseph-conrad_heart-of-darkness', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '1ff37340-ef72-53dd-8552-e48f46ee46de';
update public.livros set resumo = 'Almustafa, o profeta, passou doze anos na cidade de Orphalese e espera um navio que o levará para casa. Antes de partir, o povo lhe pede conselhos sobre o amor, o casamento, os filhos, o trabalho, a alegria, a dor e a morte. As respostas vêm em vinte e seis textos curtos, em prosa poética, que se leem em poucos minutos cada um.', resumo_en = 'Almustafa, the prophet, has spent twelve years in the city of Orphalese and waits for a ship to take him home. Before he leaves, the people ask him for advice on love, marriage, children, work, joy, sorrow and death. His answers come in twenty-six short pieces of poetic prose, each readable in a few minutes.', texto_no_app = true, texto_slug = 'kahlil-gibran_the-prophet', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '7a80458e-3f9a-542e-9640-5022488b32a0';
update public.livros set resumo = 'A Toupeira, cansada da faxina de primavera, sai de casa e conhece o Rato d''Água na beira do rio. Os dois fazem amizade com o sábio Texugo e o Sapo, rico e doido por carros, que acaba preso por roubá-los. Quando o Sapo foge, os amigos tentam retomar o castelo dele, tomado pelos furões e doninhas da Floresta Selvagem.', resumo_en = 'The Mole, tired of spring-cleaning, leaves home and meets the Water Rat on the river bank. The two befriend the wise Badger and Toad, rich and crazy about motor cars, who ends up in jail for stealing them. When Toad escapes, his friends try to retake his home, seized by the weasels and stoats of the Wild Wood.', texto_no_app = true, texto_slug = 'kenneth-grahame_the-wind-in-the-willows', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '21bd1db0-285d-5df7-932e-13e9b7f7cff2';
update public.livros set resumo = 'Um ciclone leva a casa de Dorothy, do Kansas, até a terra de Oz. Para voltar, ela segue a estrada de tijolos amarelos até a Cidade das Esmeraldas, onde mora o Mágico, e no caminho faz amizade com o Espantalho, o Homem de Lata e o Leão Covarde, cada um em busca de algo. No livro, os sapatos mágicos são de prata, não vermelhos como no filme.', resumo_en = 'A cyclone carries Dorothy''s house from Kansas to the Land of Oz. To get home, she follows the yellow brick road to the Emerald City, where the Wizard lives, and on the way befriends the Scarecrow, the Tin Woodman and the Cowardly Lion, each looking for something. In the book the magic shoes are silver, not red as in the film.', texto_no_app = true, texto_slug = 'l-frank-baum_the-wonderful-wizard-of-oz', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '856bab55-3a37-55f8-a16a-7b6e8367255f';
update public.livros set resumo = 'Os irmãos Marilla e Matthew Cuthbert pedem um menino para ajudar na fazenda, mas por engano chega Anne Shirley, uma órfã de onze anos, ruiva e muito falante. Ela transforma a vida em Avonlea, na Ilha do Príncipe Eduardo, com a imaginação, a amizade com Diana e a rivalidade com Gilbert Blythe. A história acompanha seu crescimento até a idade adulta.', resumo_en = 'The siblings Marilla and Matthew Cuthbert ask for a boy to help on the farm, but by mistake they get Anne Shirley, an eleven-year-old redheaded orphan who never stops talking. She transforms life in Avonlea, on Prince Edward Island, with her imagination, her friendship with Diana and her rivalry with Gilbert Blythe. The story follows her growing up into adulthood.', texto_no_app = true, texto_slug = 'l-m-montgomery_anne-of-green-gables', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '3216d8c2-9903-514e-8c4b-dad9d196cafc';
update public.livros set resumo = 'Numa tarde quente, Alice segue um coelho branco de colete até uma toca e cai num mundo onde tudo muda de tamanho e de regra. Ela encontra o Gato de Cheshire, o Chapeleiro Maluco num chá sem fim e a Rainha de Copas, que manda cortar cabeças por qualquer coisa. O livro brinca com a lógica, a linguagem e o jeito dos sonhos.', resumo_en = 'On a warm afternoon, Alice follows a white rabbit in a waistcoat down a hole and falls into a world where everything changes size and rules. She meets the Cheshire Cat, the Mad Hatter at a never-ending tea party and the Queen of Hearts, who orders beheadings over nothing. The book plays with logic, language and the way dreams work.', texto_no_app = true, texto_slug = 'lewis-carroll_alices-adventures-in-wonderland', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '7b6cfc3b-fc47-5a80-9fee-686c9f2a5da4';
update public.livros set resumo = 'Alice atravessa o espelho da sala e chega a um mundo organizado como um tabuleiro de xadrez, onde tudo é ao contrário. Ela encontra a Rainha Vermelha, os gêmeos Tweedledum e Tweedledee, o Humpty Dumpty e o poema do Jabberwocky. Seu objetivo é chegar ao último quadrado para virar rainha.', resumo_en = 'Alice steps through the drawing-room mirror into a world laid out like a chessboard, where everything runs backwards. She meets the Red Queen, the twins Tweedledum and Tweedledee, Humpty Dumpty and the poem of the Jabberwocky. Her goal is to reach the last square and become a queen.', texto_no_app = true, texto_slug = 'lewis-carroll_through-the-looking-glass', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '19d8ef05-d878-5112-9771-d57256652724';
update public.livros set resumo = 'Hank Morgan, mecânico de uma fábrica de Connecticut, leva uma pancada na cabeça e acorda no ano 528, na corte do rei Arthur. Usa o que sabe de ciência, como a previsão de um eclipse, para virar o homem mais poderoso do reino, o Chefe. Tenta trazer telégrafo, escolas e fábricas, mas a Igreja e os cavaleiros resistem, e o final é de guerra.', resumo_en = 'Hank Morgan, a foreman at a Connecticut factory, gets a blow to the head and wakes up in the year 528 at King Arthur''s court. He uses what he knows of science, such as predicting an eclipse, to become the most powerful man in the kingdom, the Boss. He tries to bring in telegraphs, schools and factories, but the Church and the knights resist, and the ending is war.', texto_no_app = true, texto_slug = 'mark-twain_a-connecticut-yankee-in-king-arthurs-court', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '942f9ee7-5c6f-5a60-9b32-e1065483d79e';
update public.livros set resumo = 'Em St Petersburg, uma cidade às margens do Mississippi, Tom Sawyer foge da escola, engana os amigos para caiarem a cerca da tia Polly e se apaixona por Becky Thatcher. À noite, no cemitério, ele e Huck Finn veem um assassinato cometido pelo Injun Joe. O medo de contar a verdade os leva a uma caverna, onde Tom e Becky se perdem.', resumo_en = 'In St Petersburg, a town on the Mississippi, Tom Sawyer skips school, tricks his friends into whitewashing Aunt Polly''s fence and falls for Becky Thatcher. One night in the graveyard he and Huck Finn witness a murder committed by Injun Joe. Fear of telling the truth leads them into a cave, where Tom and Becky get lost.', texto_no_app = true, texto_slug = 'mark-twain_the-adventures-of-tom-sawyer', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '16c377ca-d0ce-5ab7-9730-bb7fc01787ed';
update public.livros set resumo = 'Na Londres de 1547, o príncipe Edward e o menino pobre Tom Canty, que são idênticos, trocam de roupa por brincadeira. Tom é levado ao palácio e todos acham que ele é o príncipe; Edward, expulso, passa pelas ruas e conhece a miséria. Com a ajuda do cavaleiro Miles Hendon, Edward luta para voltar antes da coroação.', resumo_en = 'In London in 1547, Prince Edward and the poor boy Tom Canty, who look exactly alike, swap clothes as a game. Tom is taken into the palace and everyone thinks he is the prince; Edward, thrown out, wanders the streets and sees poverty first-hand. With the help of the knight Miles Hendon, Edward struggles to return before the coronation.', texto_no_app = true, texto_slug = 'mark-twain_the-prince-and-the-pauper', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'cd7bb947-1534-5b22-aadf-32bbf9f34ccc';
update public.livros set resumo = 'O estudante Victor Frankenstein monta uma criatura com partes de corpos e a faz viver, mas foge horrorizado e a abandona. Rejeitada por todos, a criatura aprende a falar lendo livros, procura o criador e pede uma companheira. Quando Victor se recusa, ela se vinga dele, e a história, contada nas cartas de um capitão no Ártico, termina em perseguição.', resumo_en = 'The student Victor Frankenstein builds a creature from body parts and brings it to life, but flees in horror and abandons it. Rejected by everyone, the creature teaches itself to speak by reading books, seeks out its maker and asks for a companion. When Victor refuses, the creature takes revenge, and the story, told through the letters of a captain in the Arctic, ends in pursuit.', texto_no_app = true, texto_slug = 'mary-shelley_frankenstein', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '17806d25-8ea6-5712-b0f5-24591f11eb17';
update public.livros set resumo = 'Na Boston puritana do século XVII, Hester Prynne tem uma filha, Pearl, fora do casamento e é obrigada a usar no peito a letra A, de adúltera. Ela se recusa a revelar quem é o pai. Enquanto isso o pastor Arthur Dimmesdale esconde o segredo e adoece de culpa, e o marido de Hester, agora com outro nome, procura vingança.', resumo_en = 'In seventeenth-century Puritan Boston, Hester Prynne has a daughter, Pearl, outside marriage and is made to wear a scarlet A on her chest for adultery. She refuses to name the father. Meanwhile the minister Arthur Dimmesdale hides the secret and sickens with guilt, and Hester''s husband, now under another name, seeks revenge.', texto_no_app = true, texto_slug = 'nathaniel-hawthorne_the-scarlet-letter', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'b0de4863-d9d8-5ee7-9753-0c1694d6eeca';
update public.livros set resumo = 'Sir Robert Chiltern é um político respeitado, casado com uma mulher que o admira como a um homem perfeito. A senhora Cheveley aparece com uma carta que prova que, no começo da carreira, ele vendeu um segredo de Estado, e o chantageia. Para sair do aperto, Robert recorre ao amigo irônico Lord Goring, e o casal precisa aprender a perdoar.', resumo_en = 'Sir Robert Chiltern is a respected politician, married to a woman who admires him as a perfect man. Mrs Cheveley arrives with a letter proving that early in his career he sold a state secret, and she blackmails him. To get out of the trap, Robert turns to his witty friend Lord Goring, and the couple must learn to forgive.', texto_no_app = true, texto_slug = 'oscar-wilde_an-ideal-husband', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '81a61276-a179-5e61-b0b3-98333767cc86';
update public.livros set resumo = 'Jack Worthing e Algernon Moncrieff inventam identidades falsas para escapar de obrigações, mas ambos dizem se chamar Ernest quando se apaixonam por Gwendolen e Cecily, que só aceitam casar com um homem com esse nome. Entre confusões, uma bolsa de mão esquecida e a lady Bracknell, a peça ridiculariza as regras da boa sociedade com diálogos rápidos.', resumo_en = 'Jack Worthing and Algernon Moncrieff invent false identities to escape their obligations, but both claim to be called Ernest when they fall for Gwendolen and Cecily, who will only marry a man with that name. With mix-ups, a forgotten handbag and Lady Bracknell, the play mocks the rules of polite society in rapid-fire dialogue.', texto_no_app = true, texto_slug = 'oscar-wilde_the-importance-of-being-earnest', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '07157d66-c4d8-50a1-8d2e-88405b3fccf9';
update public.livros set resumo = 'O pintor Basil Hallward faz o retrato do belo Dorian Gray, e Lord Henry Wotton o convence de que a juventude é tudo o que importa. Dorian deseja que o quadro envelheça no lugar dele, e o desejo se realiza. Enquanto leva uma vida cada vez mais cruel, o rosto de Dorian continua intacto e a pintura guarda o preço de cada ato.', resumo_en = 'The painter Basil Hallward paints the handsome Dorian Gray, and Lord Henry Wotton convinces him that youth is all that matters. Dorian wishes the portrait would age in his place, and the wish comes true. As he leads an ever crueller life, Dorian''s face stays untouched while the painting records the price of every act.', texto_no_app = true, texto_slug = 'oscar-wilde_the-picture-of-dorian-gray', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'e52fcdb4-6d72-5534-b5f9-d3beb9940cee';
update public.livros set resumo = 'Em 1751, o órfão David Balfour, de dezessete anos, vai ao encontro do tio Ebenezer, que o engana e o vende a um navio rumo à América. Depois de um naufrágio, David encontra o jacobita Alan Breck Stewart, e os dois fogem pelas montanhas da Escócia, perseguidos pelos soldados ingleses. A amizade entre eles, tão diferentes, dá força à aventura.', resumo_en = 'In 1751 the seventeen-year-old orphan David Balfour goes to meet his uncle Ebenezer, who tricks him and sells him to a ship bound for America. After a shipwreck David meets the Jacobite Alan Breck Stewart, and the two flee across the Scottish Highlands, hunted by English soldiers. Their friendship, between two very different men, powers the adventure.', texto_no_app = true, texto_slug = 'robert-louis-stevenson_kidnapped', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'e0d24b09-f264-541f-98f2-ab045be06c23';
update public.livros set resumo = 'Jim Hawkins, filho de uma estalajadeira, encontra um mapa do tesouro entre as coisas de um velho pirata morto. Ele embarca no navio Hispaniola com o fidalgo Trelawney, o doutor Livesey e o cozinheiro de uma perna só, Long John Silver, que esconde planos de motim. Na ilha, o grupo disputa o tesouro com piratas e com Ben Gunn, abandonado há anos.', resumo_en = 'Jim Hawkins, an innkeeper''s son, finds a treasure map among the belongings of a dead old pirate. He sails on the Hispaniola with Squire Trelawney, Dr Livesey and the one-legged cook Long John Silver, who hides plans for a mutiny. On the island the party fights over the treasure with pirates and with Ben Gunn, marooned for years.', texto_no_app = true, texto_slug = 'robert-louis-stevenson_treasure-island', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'e88b18ca-c47f-58a7-b481-67a60f57223d';
update public.livros set resumo = 'Kim, órfão de um soldado irlandês, vive nas ruas de Lahore, na Índia britânica, e vira discípulo de um velho lama tibetano que procura um rio sagrado. No caminho, é recrutado como espião pelo Grande Jogo, a disputa secreta entre a Inglaterra e a Rússia. O livro é uma aventura pela estrada, cheia de cores, línguas e religiões da Índia.', resumo_en = 'Kim, orphan of an Irish soldier, lives on the streets of Lahore in British India and becomes the disciple of an old Tibetan lama searching for a sacred river. Along the way he is recruited as a spy in the Great Game, the secret struggle between Britain and Russia. The book is a road adventure full of the colours, languages and religions of India.', texto_no_app = true, texto_slug = 'rudyard-kipling_kim', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '8cfb080f-e206-5045-b25c-45b9e53cc9e6';
update public.livros set resumo = 'Mogli, um menino criado por lobos na selva indiana, aprende a Lei da Selva com o urso Balu e a pantera Bagheera. O tigre Shere Khan quer matá-lo, e Mogli precisa decidir entre os animais e o povo da aldeia. Os contos incluem também Rikki-Tikki-Tavi, a mangusto que defende uma casa de cobras.', resumo_en = 'Mowgli, a boy raised by wolves in the Indian jungle, learns the Law of the Jungle from Baloo the bear and Bagheera the panther. The tiger Shere Khan wants to kill him, and Mowgli must choose between the animals and the people of the village. The stories also include Rikki-Tikki-Tavi, the mongoose who defends a house from snakes.', texto_no_app = true, texto_slug = 'rudyard-kipling_the-jungle-book', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'fbef09e7-db10-5417-af10-e2be75c0f9aa';
update public.livros set resumo = 'Numa feira rural, o lavrador Michael Henchard, bêbado, vende a esposa Susan e a filha pequena por cinco guinéus. Dezoito anos depois, é o prefeito respeitado de Casterbridge, mas Susan reaparece e o segredo volta à tona. Com o orgulho, o temperamento e a rivalidade com o jovem escocês Donald Farfrae, Henchard destrói a própria vida.', resumo_en = 'At a country fair, the labourer Michael Henchard, drunk, sells his wife Susan and baby daughter for five guineas. Eighteen years later he is the respected mayor of Casterbridge, but Susan reappears and the secret resurfaces. Through pride, temper and rivalry with the young Scotsman Donald Farfrae, Henchard destroys his own life.', texto_no_app = true, texto_slug = 'thomas-hardy_the-mayor-of-casterbridge', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '23ba3531-301b-57f4-98c2-57c8fb2b1b03';
update public.livros set resumo = 'Em Atenas, Hermia ama Lysander, mas o pai quer casá-la com Demetrius, e Helena, apaixonada por Demetrius, os segue pela floresta. Lá, o rei das fadas, Oberon, manda o duende Puck pingar uma poção do amor nos olhos errados, e tudo se embaralha. Enquanto isso, o tecelão Bottom ganha cabeça de burro e conquista a rainha Titânia.', resumo_en = 'In Athens, Hermia loves Lysander, but her father wants her to marry Demetrius, and Helena, who loves Demetrius, follows them into the forest. There the fairy king Oberon sends the sprite Puck to drip a love potion into the wrong eyes, and everything gets tangled. Meanwhile the weaver Bottom gets a donkey''s head and wins the fairy queen Titania.', texto_no_app = true, texto_slug = 'william-shakespeare_a-midsummer-nights-dream', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'd52ac548-6102-5af4-9ce8-b5f44cb80cd5';
update public.livros set resumo = 'Banida pelo tio, o duque Frederick, Rosalinda foge para a Floresta de Arden com a prima Celia e o bobo Touchstone, disfarçada de rapaz. Lá reencontra Orlando, que a ama, e o testa sem se revelar. Entre canções, poemas pendurados nas árvores e casamentos finais, a peça traz o célebre discurso de que o mundo todo é um palco.', resumo_en = 'Banished by her uncle Duke Frederick, Rosalind flees to the Forest of Arden with her cousin Celia and the fool Touchstone, disguised as a young man. There she meets Orlando again, who loves her, and tests him without revealing herself. Between songs, poems hung on trees and final weddings, the play holds the famous speech about the world being a stage.', texto_no_app = true, texto_slug = 'william-shakespeare_as-you-like-it', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '5d30b764-e8f9-5de8-bd91-45555efb9b3d';
update public.livros set resumo = 'O príncipe Hamlet, da Dinamarca, recebe a visita do fantasma do pai, que conta ter sido envenenado pelo irmão, Cláudio, agora rei e casado com a viúva. Para ter certeza, Hamlet finge loucura e encena uma peça diante da corte. A dúvida entre agir e esperar custa a vida de Ofélia, Polônio e, num duelo final, de quase todos.', resumo_en = 'Prince Hamlet of Denmark is visited by the ghost of his father, who says he was poisoned by his brother Claudius, now king and married to the widow. To be sure, Hamlet feigns madness and stages a play before the court. His doubt between acting and waiting costs the lives of Ophelia, Polonius and, in a final duel, almost everyone.', texto_no_app = true, texto_slug = 'william-shakespeare_hamlet', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'dac2b2e2-b978-5032-b477-2a5a8fbf4843';
update public.livros set resumo = 'O jovem rei Henrique V, antes conhecido pelas farras, reivindica o trono da França e leva o exército inglês a atravessar o Canal. Depois do cerco de Harfleur, as tropas cansadas e doentes enfrentam um exército muito maior em Azincourt. O discurso da irmandade de quem luta ao lado do rei é um dos mais famosos do teatro.', resumo_en = 'The young King Henry V, once known for wild living, claims the throne of France and leads the English army across the Channel. After the siege of Harfleur, his tired and sick troops face a much larger army at Agincourt. His speech on the brotherhood of those who fight beside the king is one of the best known in drama.', texto_no_app = true, texto_slug = 'william-shakespeare_henry-v', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '0c2b6827-54bc-594c-bef6-cda4645c8615';
update public.livros set resumo = 'Em Roma, Brutus e Cássio temem que Júlio César queira virar rei e organizam uma conspiração para matá-lo nos Idos de Março. Depois do assassinato, Marco Antônio faz um discurso no funeral que vira o povo contra os conspiradores. A guerra civil termina em Filipos, e Brutus, mesmo vencido, é tratado como um homem de honra.', resumo_en = 'In Rome, Brutus and Cassius fear that Julius Caesar means to become king and plot to kill him on the Ides of March. After the assassination Mark Antony gives a funeral speech that turns the people against the conspirators. The civil war ends at Philippi, and Brutus, though beaten, is remembered as a man of honour.', texto_no_app = true, texto_slug = 'william-shakespeare_julius-caesar', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '2fba02a7-bf3e-5eca-9be6-80f7e6c3e799';
update public.livros set resumo = 'O velho rei Lear decide dividir o reino entre as três filhas conforme o amor que declaram. Goneril e Regan o adulam; Cordélia, que não sabe bajular, é deserdada. Traído pelas duas, Lear vaga numa tempestade ao lado do Bobo, enquanto, numa história paralela, o conde de Gloucester é enganado pelo filho bastardo Edmund.', resumo_en = 'The old King Lear decides to divide his kingdom among his three daughters according to how much love they declare. Goneril and Regan flatter him; Cordelia, who cannot flatter, is disinherited. Betrayed by the other two, Lear wanders in a storm beside his Fool, while in a parallel plot the Earl of Gloucester is deceived by his bastard son Edmund.', texto_no_app = true, texto_slug = 'william-shakespeare_king-lear', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '4767989f-79f7-5664-8e0a-d6cff84593d6';
update public.livros set resumo = 'Três bruxas dizem ao general escocês Macbeth que ele será rei, e a esposa, lady Macbeth, o empurra para assassinar o rei Duncan. Depois do crime, Macbeth manda matar também o amigo Banquo e passa a ver o fantasma dele. A culpa enlouquece o casal, e a profecia da floresta de Birnam se cumpre de um jeito que ele não esperava.', resumo_en = 'Three witches tell the Scottish general Macbeth that he will be king, and his wife, Lady Macbeth, pushes him to murder King Duncan. After the crime, Macbeth has his friend Banquo killed too and begins to see his ghost. Guilt drives the couple mad, and the prophecy about Birnam Wood comes true in a way he never expected.', texto_no_app = true, texto_slug = 'william-shakespeare_macbeth', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'd4099b96-ed59-5f8b-b03b-e97637d24de7';
update public.livros set resumo = 'Em Messina, os soldados voltam da guerra, e Beatriz e Benedito, que vivem trocando farpas, são enganados pelos amigos, que os fazem acreditar que cada um ama o outro em segredo. Em paralelo, o vilão Dom João arma uma intriga que quase destrói o casamento de Cláudio e Hero. Os guardas atrapalhados do guarda-mor Dogberry ajudam a revelar a verdade.', resumo_en = 'In Messina the soldiers return from war, and Beatrice and Benedick, who trade barbs constantly, are tricked by their friends into believing each secretly loves the other. In parallel, the villain Don John hatches a plot that nearly destroys the wedding of Claudio and Hero. The bumbling watchmen led by Dogberry help bring out the truth.', texto_no_app = true, texto_slug = 'william-shakespeare_much-ado-about-nothing', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'bafb5c0a-0a3c-5d9f-98e8-44b3afdca8b8';
update public.livros set resumo = 'O general mouro Otelo, a serviço de Veneza, se casa em segredo com Desdêmona e é enviado a Chipre. Iago, ressentido por ter sido preterido na promoção, planta a suspeita de que a esposa o trai com o tenente Cássio, usando um lenço como falsa prova. O ciúme leva Otelo a cometer um crime que ele só entende tarde demais.', resumo_en = 'The Moorish general Othello, in Venice''s service, secretly marries Desdemona and is sent to Cyprus. Iago, bitter at being passed over for promotion, plants the suspicion that his wife is unfaithful with the lieutenant Cassio, using a handkerchief as false proof. Jealousy drives Othello to a crime he understands only too late.', texto_no_app = true, texto_slug = 'william-shakespeare_othello', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '51ed7df0-21fd-5f47-9af0-6bf3374d07fc';
update public.livros set resumo = 'Ricardo, duque de Gloucester, deformado e cheio de ambição, abre a peça dizendo que o inverno do descontentamento chegou. Com charme e crueldade ele elimina o irmão Clarence, casa com Anne e manda prender os dois sobrinhos na Torre de Londres para tomar a coroa. Seu reinado dura pouco: na batalha de Bosworth, o conde de Richmond o derrota.', resumo_en = 'Richard, Duke of Gloucester, deformed and full of ambition, opens the play declaring that the winter of discontent has come. With charm and cruelty he eliminates his brother Clarence, marries Anne and has his two nephews locked in the Tower of London to seize the crown. His reign is short: at the Battle of Bosworth the Earl of Richmond defeats him.', texto_no_app = true, texto_slug = 'william-shakespeare_richard-iii', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '9a75290a-8d00-5ee0-8870-e6e254f4f310';
update public.livros set resumo = 'Em Verona, as famílias Montéquio e Capuleto vivem em guerra, mas Romeu e Julieta se conhecem num baile de máscaras e se apaixonam. Frei Lourenço os casa em segredo, e uma briga de rua termina com a morte de Mercúcio e Teobaldo e o exílio de Romeu. Um plano para fingir a morte de Julieta dá errado, e os dois acabam mortos, o que enfim reconcilia as famílias.', resumo_en = 'In Verona, the Montague and Capulet families are at war, but Romeo and Juliet meet at a masked ball and fall in love. Friar Laurence marries them in secret, and a street fight ends with the deaths of Mercutio and Tybalt and Romeo''s exile. A plan to fake Juliet''s death goes wrong, and both end up dead, which finally reconciles the families.', texto_no_app = true, texto_slug = 'william-shakespeare_romeo-and-juliet', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '1de18b3c-a31d-58b8-8cf3-8dc026024011';
update public.livros set resumo = 'Bassanio quer pedir a mão da rica Pórcia e consegue o dinheiro por meio do amigo Antônio, que toma emprestado do agiota Shylock com um contrato horrível: se não pagar a tempo, dará uma libra da própria carne. Quando os navios de Antônio se perdem, a dívida vai a julgamento, e Pórcia, disfarçada de advogado, decide o caso. A peça trata de justiça, misericórdia e preconceito.', resumo_en = 'Bassanio wants to court the wealthy Portia and gets the money through his friend Antonio, who borrows from the moneylender Shylock under a terrible bond: if he fails to repay in time, he forfeits a pound of his own flesh. When Antonio''s ships are lost, the debt goes to trial, and Portia, disguised as a lawyer, decides the case. The play deals with justice, mercy and prejudice.', texto_no_app = true, texto_slug = 'william-shakespeare_the-merchant-of-venice', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '48288173-a071-546c-b1b7-6c9d45b0be66';
update public.livros set resumo = 'Em Pádua, o pai de Catarina e Bianca só deixará casar a mais nova depois que a geniosa mais velha encontrar marido. Petruchio, em busca de fortuna, aceita o desafio e tenta dominar Catarina com comportamentos exagerados. A peça é encenada para o bêbado Christopher Sly, e o final, em que Catarina fala sobre obediência, é muito discutido hoje.', resumo_en = 'In Padua, the father of Katherina and Bianca will only let the younger one marry after the sharp-tongued elder finds a husband. Petruchio, seeking a fortune, takes up the challenge and tries to tame Katherina with exaggerated behaviour. The play is staged for the drunkard Christopher Sly, and the ending, in which Katherina speaks about obedience, is much debated today.', texto_no_app = true, texto_slug = 'william-shakespeare_the-taming-of-the-shrew', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = '01038c54-bda8-52ea-9596-1bfa318a3154';
update public.livros set resumo = 'Próspero, antigo duque de Milão, vive numa ilha há doze anos com a filha Miranda, o espírito Ariel e o escravo Caliban. Ao saber que o irmão traidor passa de navio por ali, provoca uma tempestade e traz todos para a ilha. Entre feitiços, o amor de Miranda por Ferdinand e uma conspiração desajeitada, ele escolhe perdoar e abrir mão de sua magia.', resumo_en = 'Prospero, the former Duke of Milan, has lived on an island for twelve years with his daughter Miranda, the spirit Ariel and the slave Caliban. Learning that his treacherous brother is sailing past, he raises a storm and brings everyone ashore. Amid spells, Miranda''s love for Ferdinand and a clumsy plot, he chooses to forgive and give up his magic.', texto_no_app = true, texto_slug = 'william-shakespeare_the-tempest', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'd3ca23c4-5563-5da7-92e2-9f3cb946c0ab';
update public.livros set resumo = 'Depois de um naufrágio, Viola chega à Ilíria e, achando que o irmão gêmeo Sebastian morreu, se disfarça de rapaz com o nome de Cesário e serve ao duque Orsino. Ela se apaixona por ele, que ama a condessa Olívia, que por sua vez se apaixona por Cesário. A chegada de Sebastian e uma carta falsa que faz do mordomo Malvólio um tolo completam a confusão.', resumo_en = 'After a shipwreck, Viola arrives in Illyria and, believing her twin brother Sebastian is dead, disguises herself as a young man named Cesario and serves Duke Orsino. She falls for him, he loves the Countess Olivia, and Olivia in turn falls for Cesario. The arrival of Sebastian and a forged letter that makes a fool of the steward Malvolio complete the confusion.', texto_no_app = true, texto_slug = 'william-shakespeare_twelfth-night', texto_fonte = 'Standard Ebooks (CC0)', estante_inicial = true where id = 'bcff6682-7534-5bbe-9e1a-ef873b220030';

update public.livros set resumo = 'O historiador Yuval Noah Harari propõe que o Homo sapiens dominou o planeta por saber criar histórias em comum, como religiões, dinheiro e países, que fazem milhões de desconhecidos cooperarem. O livro passa pelas revoluções Cognitiva, Agrícola e Científica. A edição em inglês tem frases claras, adequadas ao nível intermediário.' where id = 'a90d687b-17ff-5591-8c2f-65e7354d3eb0';
update public.livros set resumo = 'Entre 1942 e 1944, a adolescente Anne Frank escreve cartas à amiga imaginária Kitty sobre a vida num esconderijo atrás de uma estante em Amsterdã, com a família e outras quatro pessoas. Fala de medo, brigas, do primeiro amor por Peter e do sonho de virar escritora. Em inglês, o texto é simples e direto, bom para o nível intermediário.' where id = '085b73e9-a0ee-5b06-991c-895265b94ee9';
update public.livros set resumo = 'Alonso Quijano, um fidalgo da Mancha, enlouquece de tanto ler livros de cavalaria e se declara o cavaleiro Dom Quixote, com o fiel escudeiro Sancho Pança ao lado. Os dois confundem moinhos com gigantes e estalagens com castelos, e o humor se mistura com a tristeza dos fracassos. Em inglês, é um clássico longo, de leitura avançada.' where id = '2e0d320a-af19-5fa8-82ae-a6078daa1710';
update public.livros set resumo = 'Dez anos depois de Troia, Ulisses ainda tenta chegar a Ítaca e enfrenta o ciclope Polifemo, as sereias, Circe e Calipso. Em casa, a esposa Penélope adia o casamento com os pretendentes que consomem os bens da família, e o filho Telêmaco parte em busca do pai. A edição em inglês é uma leitura avançada, cheia de epítetos repetidos.' where id = '1ec4c5c9-7769-5097-8c24-430b261469bc';
update public.livros set resumo = 'Nos últimos dias do cerco de Troia, Aquiles se recusa a lutar depois de uma ofensa de Agamêmnon, e os gregos sofrem derrotas. Ele só volta ao combate quando o amigo Pátroclo é morto por Heitor, e o duelo entre os dois é o ponto alto do poema. Em inglês, é uma leitura de linguagem elevada e frases longas.' where id = 'c6511ab3-0eae-581f-a226-5710fc6fed79';
update public.livros set resumo = 'Atribuído ao general chinês Sun Tzu, o tratado tem treze capítulos curtos sobre planejamento, terreno, espionagem e o uso do engano. A ideia central é vencer sem lutar sempre que possível, conhecendo a si mesmo e ao adversário. Em inglês, as frases são curtas e diretas, boas para treinar a leitura.' where id = 'c65adf5c-02be-591e-a309-5b8a52a75304';
update public.livros set resumo = 'O imperador romano Marco Aurélio escreveu estas notas para si mesmo durante campanhas militares, sem pensar em publicá-las. Elas repetem ideias estoicas: aceitar o que não depende de nós, agir com justiça e lembrar que a vida é breve. Em inglês, é um texto de frases curtas e aforismos, de nível avançado.' where id = 'decc8632-3294-5793-bd1d-26490548fda0';

